// mcui — the MoonCellar look for the Dear ImGui interfaces of MoonCellar Team's game ports: the
// launcher before the game and the overlay over it. Colours, radii, spacing and motion come from
// the site's tokens (mcui_tokens.h, generated by sync-tokens.ts); controls follow the site's
// components in Storybook. See packages/port-ui/README.md.
//
// The package draws only through ImGui: the port brings the ImGui backend, the font files and the
// textures (logos). It needs Dear ImGui 1.92 or newer.
#pragma once

#include <string>
#include <vector>

#include "imgui.h"
#include "mcui_tokens.h"

namespace mcui {

// A colour token (tokens::kColor*) as ImGui wants it
ImVec4 Color(unsigned token, float alpha = 1.0f);
ImU32 Packed(unsigned token, float alpha = 1.0f);

// Type scale, in CSS pixels before the UI scale
constexpr float kTextBody = 15.0f;
constexpr float kTextCaption = 13.0f;
constexpr float kTextTitle = 20.0f;
constexpr float kTextDisplay = 28.0f;

// ---- Fonts and style ----

// The faces the port supplies. The site's face (Apercu Pro) is a licensed file, so it never enters
// this package: the port keeps it next to its build. `fallback` — files merged into every face for
// glyphs it lacks (arrows, Chinese, Japanese, Korean); when the face itself is missing, the first
// fallback stands in for it.
struct FontFile {
    std::string path;
    int index = 0;  // the face inside a collection (.ttc)
};
struct FontFiles {
    std::string regular, medium, bold;
    std::vector<FontFile> fallback;
};

struct Fonts {
    ImFont* regular = nullptr;
    ImFont* medium = nullptr;
    ImFont* bold = nullptr;
    bool brand = false;  // the regular face was found: text is set in the brand face
};

// Adds the faces to ImGui's atlas. Call before the first frame of the context.
const Fonts& LoadFonts(const FontFiles& files);
const Fonts& GetFonts();

// ImGui's style and colours from the tokens. `scale` — the UI scale (1 at 96 dpi); fonts follow it.
void ApplyStyle(float scale = 1.0f);
float Scale();

// ---- Text ----

void Title(const char* text);    // bold, title size
void Caption(const char* text);  // muted, caption size, wrapped
// A heading of a group: an accent bar and the label (the site's SectionTitle, "bar"); below other
// content it keeps a gap above itself
void SectionTitle(const char* text);

// ---- Controls ----

enum class ButtonKind {
    Default,  // --color-bg-tertiary
    Accent,   // the primary action of a screen
    Danger,   // destructive actions
    Ghost,    // no fill until hovered
};
bool Button(const char* label, ButtonKind kind = ButtonKind::Default, ImVec2 size = ImVec2(0, 0));

// The site's ToggleSwitch: off — red knob on the left, on — green knob on the right; the label
// stands to the right and is clickable too
bool Toggle(const char* label, bool* value);

// The site's segmented Tabs; true when the choice changed
bool Segmented(const char* id, const char* const* items, int count, int* current, bool gamepadShoulders = false);

// A thin bar (the site's ProgressBar); `fraction` 0..1
void ProgressBar(float fraction, ImVec2 size = ImVec2(-1.0f, 0.0f), unsigned color = tokens::kColorAccent);

// A panel — the site's Box: --color-bg-secondary, --radius-x5. Width 0 fills the line, height 0
// fits the content.
bool BeginPanel(const char* id, ImVec2 size = ImVec2(0, 0));
void EndPanel();

// ---- Icons ----

// A 24×24 outline icon in the format of the ports' achievement icons and the site's icons:
// paths stroked 1.8 wide with round caps and joins. Parsed once, drawn in any colour and size.
struct Icon {
    struct Stroke {
        std::vector<ImVec2> points;
        std::vector<ImVec2> joints;  // corners and ends: drawn round
        bool closed = false;
    };
    std::vector<Stroke> strokes;
    bool Valid() const { return !strokes.empty(); }
};
Icon ParseIcon(const std::string& svg);
void DrawIcon(ImDrawList* list, const Icon& icon, ImVec2 pos, float size, ImU32 color);

// ---- Achievements ----

struct AchievementView {
    std::string title, description;
    std::string status;  // under the description: when it was unlocked, or how far the player is
    const Icon* icon = nullptr;
    bool unlocked = false;
    int current = -1, target = 0;  // a counter's progress; target 0 — none
};
// A card: the icon on a tile (accent when unlocked, muted when not), the texts, the progress
void AchievementCard(const AchievementView& view, float width = 0.0f);

// ---- Account ----

// Signing in with a device code: the code to type on the site and, when given, the address to
// open. The port draws its QR code next to it.
void DeviceCode(const char* code, const char* url = nullptr);

// ---- Notifications ----

struct Notification {
    std::string title, text;
    const Icon* icon = nullptr;  // drawn on an accent tile; none — the MoonCellar mark on a neutral one
    float seconds = 5.0f;
};
// Queues a notification. Safe from any thread.
void Notify(const Notification& notification);
// The port's MoonCellar mark (logo-icon) for the notification card, as an ImGui texture
void SetNotificationMark(ImTextureID mark);
// Something is queued or on screen: the overlay can skip its frame otherwise
bool NotificationsActive();
// Draws the notifications in the top right corner of the main viewport, three at a time, over
// everything else. `now` — seconds, any clock that only grows.
void DrawNotifications(double now);

}  // namespace mcui
